	private static void assertRealBounds(NativeLmdbQuerySource source, long predicate) throws Exception {
		// Extreme targets exercise metadata only: do not ask the physical planner for billions of split seeks.
		for (int target : new int[] { Integer.MIN_VALUE, -1, 0, 1, 2, 8, Integer.MAX_VALUE }) {
			assertThat(source.rootScanPartitionCountUpperBound(U, predicate, U, U, target))
					.hasValue(Math.max(1L, target));
		}
		for (int target : new int[] { 2, 8 }) {
			long cap = source.rootScanPartitionCountUpperBound(U, predicate, U, U, target).orElseThrow();
			LmdbRootScanPartition[] partitions = source.planRootScanPartitions(U, predicate, U, U, target);
			assertThat(partitions).isNotNull().isNotEmpty();
			assertThat(partitions.length).isLessThanOrEqualTo((int) cap);
			Set<Long> subjects = new HashSet<>();
			int records = 0;
			for (LmdbRootScanPartition partition : partitions) {
				try (RecordIterator scan = source.statements(U, predicate, U, U, partition)) {
					long[] quad;
					while ((quad = scan.next()) != null) {
						assertThat(subjects.add(quad[0])).as("physical ranges must be disjoint").isTrue();
						records++;
					}
				}
			}
			assertThat(records).isEqualTo(64);
		}
	}

